--
-- Name: v_cati; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_cati AS
 WITH guncel AS (
         SELECT DISTINCT ON (s.cati_id) s.cati_id,
            s.tarama_id,
            s.geom,
            s.geom_uygun,
            s.geometri_kaynagi,
            s.supheli,
            s.panel_durumu,
            s.cati_alan_m2,
            s.uygun_alan_m2,
            s.kwp,
            s.kwh_yil,
            s.kwh_alt,
            s.kwh_ust,
            s.tarife_kr_kwh,
            s.yatirim_tl,
            s.npv_tl,
            s.geri_odeme_yil,
            s.npv_p10,
            s.npv_p50,
            s.npv_p90,
            s.p_npv_poz,
            s.ilk100_orani,
            s.grup_ilk_orani
           FROM public.cati_sonuc s
          ORDER BY s.cati_id, s.tarama_id DESC
        ), siralar AS (
         SELECT g_1.cati_id,
            row_number() OVER (ORDER BY g_1.npv_tl DESC, g_1.cati_id) AS sira_npv,
            row_number() OVER (ORDER BY g_1.kwh_yil DESC, g_1.cati_id) AS sira_uretim,
            row_number() OVER (ORDER BY ((g_1.npv_tl)::numeric / g_1.kwp) DESC, g_1.cati_id) AS sira_npv_kwp,
                CASE
                    WHEN (c_1.grup <> 'diger'::text) THEN row_number() OVER (PARTITION BY c_1.grup ORDER BY g_1.npv_tl DESC, g_1.cati_id)
                    ELSE NULL::bigint
                END AS sira_grup
           FROM (guncel g_1
             JOIN public.cati c_1 USING (cati_id))
          WHERE (g_1.panel_durumu <> 'tam_dolu'::text)
        )
 SELECT c.cati_id,
    c.osm,
    c.bolge_kod,
    c.tur,
    c.grup,
    c.kurum_ad,
    t.kod AS tarama,
    g.tarama_id,
    g.geometri_kaynagi,
    g.supheli,
    g.panel_durumu,
    g.cati_alan_m2,
    g.uygun_alan_m2,
    g.kwp,
    g.kwh_yil,
    g.kwh_alt,
    g.kwh_ust,
    g.tarife_kr_kwh,
    g.yatirim_tl,
    g.npv_tl,
    round(((g.npv_tl)::numeric / NULLIF(g.kwp, (0)::numeric))) AS npv_tl_kwp,
    g.geri_odeme_yil,
    g.npv_p10,
    g.npv_p50,
    g.npv_p90,
    g.p_npv_poz,
    g.ilk100_orani,
    g.grup_ilk_orani,
    r.sira_npv,
    r.sira_uretim,
    r.sira_npv_kwp,
    r.sira_grup,
    ((a.cati_id IS NOT NULL) AND a.sayilar_tutarli) AS aciklama_var,
    public.st_pointonsurface(g.geom) AS konum,
    g.geom,
    g.geom_uygun
   FROM ((((guncel g
     JOIN public.cati c USING (cati_id))
     JOIN public.tarama t ON ((t.tarama_id = g.tarama_id)))
     LEFT JOIN siralar r USING (cati_id))
     LEFT JOIN public.cati_aciklama a ON (((a.cati_id = g.cati_id) AND (a.tarama_id = g.tarama_id))));


--
-- Name: v_ozet; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_ozet AS
 SELECT bolge_kod,
    tur,
    count(*) AS cati,
    count(*) FILTER (WHERE (panel_durumu <> 'tam_dolu'::text)) AS potansiyelli_cati,
    count(*) FILTER (WHERE (panel_durumu <> 'panel_yok'::text)) AS mevcut_ges_cati,
    round(sum(cati_alan_m2)) AS cati_alan_m2,
    round(sum(uygun_alan_m2)) AS uygun_alan_m2,
    round((sum(kwp) / (1000)::numeric), 2) AS mwp,
    round(((sum(kwh_yil))::numeric / '1000000'::numeric), 2) AS gwh_yil,
    round((sum(yatirim_tl) / '1000000'::numeric), 1) AS yatirim_milyon_tl,
    round((sum(npv_tl) / '1000000'::numeric), 1) AS npv_milyon_tl
   FROM public.v_cati
  GROUP BY bolge_kod, tur;


